        {num, select,
          0 {Email values are case-sensitive. If you use email addresses to map users between Amplitude and Marketo, the email addresses must be consistent between both systems.}
          1 {Amplitude users that don't already exist in Marketo are generated automatically by Marketo.}
        }
      }
      moengage {
        {num, select,
          0 {To use this integration, you need a MoEngage account}
          1 {You need to have an Amplitude user property that matches the User ID field in MoEngage.}
        }
      }
      netcore_cloud {
        {num, select,
          0 {This integration is only available for customers who have paid plans with Amplitude.}
          1 {To schedule daily and hourly syncs, you need at least an Amplitude Plus Plan.}
        }
      }
      notivize {
        {num, select,
          0 {This integration is only available for customers who have paid plans with Amplitude.}
          1 {To schedule daily and hourly syncs, you need at least an Amplitude Plus Plan.}
        }
      }
      onesignal {
        {num, select,
          0 {This integration is only available for customers who have paid plans with both OneSignal and Amplitude.}
          1 {This integration must be enabled on a per-project basis.}
