          3 {The Amplitude Integration is available with OneSignal Growth package and higher tiers. Contact OneSignal Support if you have any questions.}
        }
      }
      productboard {
        {num, select,
          0 {This integration is only available for customers who have paid plans with Amplitude.}
          1 {With this integration, you can choose whether to use Amplitude User_ID, Email, or both as the user identifier for matching users across Amplitude and Productboard.}
        }
