eventStreaming.considerations:
{connectionName, select,
    appsflyer {
      {num, select,
        0 {A user must exist in AppsFlyer to send events for them. Amplitude sends the event data with the user_id, which must match the customer_user_id within AppsFlyer. Make sure that the AppsFlyer customer_user_id and the Amplitude user_id match.}
        1 {Amplitude forwards all event, user, and group properties as key-value pairs within the event value.}
        2 {Amplitude sends the "os" property. AppsFlyer recommends including it because, for iOS apps, if the "os" property isn't included, AppsFlyer records the data as coming from a device running iOS 14.5.}
        3 {Amplitude sends device identifiers if available. See the AppFlyer documentation for more information about what happens if you don't send a device identifier.}
        4 {Amplitude attempts to send the device identifiers listed in the AppsFlyer documentation.}
      }
    }
    kinesis_datastream {
      {num, select,
        0 {Amplitude sends the user_id, event_name, and created_at along with all user, group, and event properties to Kinesis streams.}
        1 {The data Amplitude posts in Kinesis is the same JSON as documented in the Amplitude Export API.}
        2 {This destination supports Identify Forwarding. Anytime you make an Identify call to Amplitude, Amplitude forwards that user information. See Identify documentation for more information.}
        3 {The Role Name must have this format: arn:aws:iam::<your AWS account ID>:role/<role name>}
      }
    }
    kinesis_firehose {
      {num, select,
        0 {Amplitude sends the user_id, event_name, and created_at along with all user, group, and event properties to Kinesis streams.}
        1 {The data Amplitude posts in Kinesis is the same JSON as documented in the Amplitude Export API.}
        2 {This destination supports Identify Forwarding. Anytime you make an Identify call to Amplitude, Amplitude forwards that user information. See Identify documentation for more information.}
        3 {The Role Name must have this format: arn:aws:iam::<your AWS account ID>:role/<role name>}
      }
    }
    braze {
      {num, select,
        0 {You must have a Braze account.}
        1 {If a user with the provided Braze identifier doesn't exist within Braze, Braze creates a user with that ID. If this isn't the desired behavior, check the Update Users Only option.}
      }
    }
    customer_io {
      {num, select,
        0 {Amplitude matches the user_id to the "id" within Customer.io to associate events. If a user with that ID doesn't exist within Customer.io, a user is created. Make sure that the Amplitude user_id field matches the Customer.io id field to avoid user duplication.}
        1 {Amplitude sends events to Customer.io as an "event" event type, including mobile and webpage views. See the Customer.io API reference for more details.}
        2 {Amplitude sends all user, event, and group properties along with the event.}
      }
    }
    google_analytics_4_firebase {
      {num, select,
        0 {Amplitude sets "non_personalized_ads" to true for all sent events.}
        1 {Google Analytics 4 property names can only be composed of alphanumeric characters and underscores. Amplitude replaces white spaces in property names with a single underscore and removes all other non-alphanumeric characters from the names.}
        2 {Amplitude uses the Amplitude "event_type" as the event name when sending custom events.}
      }
    }
    pubsub {
      {num, select,
        0 {Amplitude sends the "user_id", "event_name", and "created_at" along with all user, group, and event properties to Pub/Sub.}
        1 {The data that Amplitude posts in Pub/Sub is the same JSON format as documented in the Amplitude Export API.}
        2 {This destination supports Identify Forwarding. When an Identify call is made to Amplitude, Amplitude forwards that user information. Refer to the Identify documentation for more information.}
        3 {The Google Cloud Service Account must be entered as a base64 encoded string.}
      }
    }
    intercom {
      {num, select,
        0 {Amplitude sends the "user_id", "created_at", and "event_name" to Intercom.}
        1 {A user must already exist in Intercom to send events for them. Amplitude sends the event data with the "user_id", which Intercom uses to associate the event with an existing user within Intercom. Make sure that the Intercom "user_id" and the Amplitude "user_id" match.}
        2 {Intercom has a limit of 120 Event Types and 20 metadata (which are event properties) per Event Type. Use the Event Filter while creating or editing the Event Streaming connection in Amplitude to select the events that you want to forward to Intercom.}
        3 {If you have Intercom configured as a Data Source in Amplitude, the "[Intercom] event.created" event is triggered whenever an event is created in Intercom, including through Amplitude's Event Streaming integration. If you do not want these stored in Amplitude, use Block & Drop filters to remove this event data from Amplitude.}
      }
    }
    iterable {
      {num, select,
        0 {You must have an Iterable account to use this integration.}
        1 {The user must already exist within Iterable to send events. The Amplitude "user_id" must match an existing user in Iterable.}
        2 {Amplitude sends "user_id", "event_name", and "created_at" to Iterable.}
      }
    }
    statsig {
      {num, select,
        0 {This integration must be enabled on a per-project basis.}
        1 {Amplitude matches the "user_id" to the "id" within Statsig to associate events. If a user with that ID does not exist in Statsig, then Statsig creates one. Make sure that the Amplitude "user_id" field matches the Statsig "id" field to avoid user duplication.}
      }
    }
    fullstory {
      {num, select,
        0 {You need to create a variant of an Amplitude Destination Plugin to forward events to FullStory. View Related Links for an example.}
      }
    }
    google_tag_manager {
      {num, select,
        0 {You need to create a variant of an Amplitude Destination Plugin to forward events to Google Tag Manager. View Related Links for an example.}
      }
    }
    hotjar {
      {num, select,
        0 {You need to create a variant of an Amplitude Destination Plugin to forward events to Hotjar. View Related Links for an example.}
      }
    }
  }

